input as(select regexp_replace(regexp_replace(lower(btrim(p_value)),'\(royal\)','','g'),'[[:space:]]+','','g') as k)
select coalesce((select 'APPROVED:'||min(key) from aliases,input where alias=k),public.be_financial_v2_township_key_v61_4_1(p_value));
$key$;
revoke all on function public.be_approved_tariff_lookup_key(text) from public;
grant execute on function public.be_approved_tariff_lookup_key(text) to authenticated,service_role;
create temporary table approved_rate_input(name text,rate bigint,special bigint,kind text) on commit drop;
-- Preserve old rates as inactive history. New Standard rates use the existing
-- Standard weight rule (3 kg included, 500 MMK per additional kg).
update public.be_parcel_tariffs_v2 t set status='INACTIVE',updated_at=now()
where t.customer_tier='STANDARD' and t.status='ACTIVE'
and exists(select 1 from approved_rate_input a where public.be_approved_tariff_lookup_key(a.name)=public.be_approved_tariff_lookup_key(t.township));
select distinct on(public.be_approved_tariff_lookup_key(name)) name,'STANDARD',rate,3,500,0,0,kind,kind,'ACTIVE',public.be_business_date(),'User-approved standard tariff reconciliation; no commitment discount'
from approved_rate_input order by public.be_approved_tariff_lookup_key(name),name
on conflict(township,customer_tier,effective_from) do update set base_tariff=excluded.base_tariff,included_kg=excluded.included_kg,extra_per_kg=excluded.extra_per_kg,tariff_zone=excluded.tariff_zone,tariff_zone_code=excluded.tariff_zone_code,status='ACTIVE',note=excluded.note,updated_at=now();
do $patch$ declare d text; begin
select pg_get_functiondef(oid) into d from pg_proc where proname='be_calculate_parcel_financial_v2_v61_8_2_legacy';
if strpos(d,'public.be_financial_v2_township_key_v61_4_1(t.township)')=0 then raise exception 'Unexpected tariff calculator definition'; end if;
d:=replace(d,'public.be_financial_v2_township_key_v61_4_1(t.township)','public.be_approved_tariff_lookup_key(t.township)');
d:=replace(d,'public.be_financial_v2_township_key_v61_4_1(p_township)','public.be_approved_tariff_lookup_key(p_township)');
execute d;
end $patch$;